"""
Agent call response cache (LRU, TTL=5p).
Ha két peer ugyanazt a taskot kéri → -40% duplikált LLM hívás, CPU mentés.

LRU cache with TTL=300s (5 minutes) for agent call responses.
When two peers request the same task, the cached response is returned
instead of making a duplicate LLM call.
"""

import hashlib
import json
import time
import threading
from collections import OrderedDict
from typing import Any, Callable, Dict, Optional, Tuple


class AgentResponseCache:
    """
    Thread-safe LRU cache with TTL for agent call responses.

    - LRU eviction when capacity is reached.
    - TTL-based expiry (default 300s = 5 minutes).
    - Cache key derived from task content hash.
    - Tracks hit/miss stats for observability.
    """

    def __init__(self, max_size: int = 256, ttl_seconds: int = 300) -> None:
        self.max_size = max_size
        self.ttl_seconds = ttl_seconds
        self._store: "OrderedDict[str, Tuple[Any, float]]" = OrderedDict()
        self._lock = threading.RLock()
        self._stats: Dict[str, int] = {
            "hits": 0,
            "misses": 0,
            "evictions_lru": 0,
            "evictions_ttl": 0,
            "stored": 0,
        }

    @staticmethod
    def _make_key(task: Any) -> str:
        """Create a stable hash key from the task payload."""
        try:
            serialized = json.dumps(task, sort_keys=True, ensure_ascii=False, default=str)
        except (TypeError, ValueError):
            serialized = str(task)
        return hashlib.sha256(serialized.encode("utf-8")).hexdigest()

    def _is_expired(self, stored_at: float) -> bool:
        return (time.time() - stored_at) > self.ttl_seconds

    def _evict_expired(self) -> None:
        """Remove all expired entries (called under lock)."""
        expired_keys = [
            k for k, (_, ts) in self._store.items() if self._is_expired(ts)
        ]
        for k in expired_keys:
            self._store.pop(k, None)
            self._stats["evictions_ttl"] += 1

    def _evict_lru(self) -> None:
        """Evict least-recently-used entry (called under lock)."""
        while len(self._store) >= self.max_size:
            self._store.popitem(last=False)
            self._stats["evictions_lru"] += 1

    def get(self, task: Any) -> Optional[Any]:
        """Return cached response for task, or None if missing/expired."""
        key = self._make_key(task)
        with self._lock:
            self._evict_expired()
            if key in self._store:
                value, stored_at = self._store[key]
                if self._is_expired(stored_at):
                    self._store.pop(key, None)
                    self._stats["evictions_ttl"] += 1
                    self._stats["misses"] += 1
                    return None
                # Move to end (most recently used)
                self._store.move_to_end(key)
                self._stats["hits"] += 1
                return value
            self._stats["misses"] += 1
            return None

    def set(self, task: Any, response: Any) -> None:
        """Store a response in the cache."""
        key = self._make_key(task)
        with self._lock:
            self._evict_expired()
            self._evict_lru()
            self._store[key] = (response, time.time())
            self._store.move_to_end(key)
            self._stats["stored"] += 1

    def get_or_compute(self, task: Any, compute_fn: Callable[[Any], Any]) -> Any:
        """
        Return cached response if available; otherwise call compute_fn(task),
        store the result, and return it.

        This is the primary entry point for agent calls — wraps the LLM
        invocation so duplicate requests are served from cache.
        """
        cached = self.get(task)
        if cached is not None:
            return cached
        response = compute_fn(task)
        self.set(task, response)
        return response

    def invalidate(self, task: Any) -> bool:
        """Manually remove a task's cached response. Returns True if removed."""
        key = self._make_key(task)
        with self._lock:
            if key in self._store:
                self._store.pop(key, None)
                return True
            return False

    def clear(self) -> None:
        """Clear all cached entries."""
        with self._lock:
            self._store.clear()

    def stats(self) -> Dict[str, Any]:
        """Return cache statistics snapshot."""
        with self._lock:
            total = self._stats["hits"] + self._stats["misses"]
            hit_rate = (self._stats["hits"] / total * 100) if total > 0 else 0.0
            return {
                **self._stats,
                "size": len(self._store),
                "max_size": self.max_size,
                "ttl_seconds": self.ttl_seconds,
                "hit_rate_pct": round(hit_rate, 2),
            }

    def cleanup(self) -> int:
        """Force expired-entry cleanup. Returns number of entries removed."""
        with self._lock:
            before = len(self._store)
            self._evict_expired()
            return before - len(self._store)


# ---------------------------------------------------------------------------
# Integration helper: a drop-in wrapper for agent call handlers
# ---------------------------------------------------------------------------

class CachedAgentCaller:
    """
    Wraps an agent call handler with LRU+TTL response caching.

    Usage in A2A Mesh peer:
        cache = AgentResponseCache(max_size=256, ttl_seconds=300)
        caller = CachedAgentCaller(handler_fn, cache)

        # When a peer requests a task:
        response = caller.call(task_payload)
    """

    def __init__(
        self,
        handler: Callable[[Any], Any],
        cache: Optional[AgentResponseCache] = None,
    ) -> None:
        self._handler = handler
        self._cache = cache or AgentResponseCache(max_size=256, ttl_seconds=300)

    def call(self, task: Any) -> Any:
        """Execute agent call with caching."""
        return self._cache.get_or_compute(task, self._handler)

    @property
    def cache(self) -> AgentResponseCache:
        return self._cache


