def _demo_llm_handler(task: Dict[str, Any]) -> Dict[str, Any]:
    """Simulated expensive LLM call."""
    time.sleep(0.5)  # simulate compute cost
    prompt = task.get("prompt", "")
    return {
        "response": f"LLM reply to: {prompt[:60]}",
        "tokens": len(prompt.split()),
        "model": "demo-llm-v1",
        "timestamp": time.time(),
    }


def main() -> None:
    print("=" * 70)
    print("Agent Response Cache — LRU + TTL=5p Demo")
    print("=" * 70)

    cache = AgentResponseCache(max_size=4, ttl_seconds=300)
    caller = CachedAgentCaller(_demo_llm_handler, cache)

    tasks = [
        {"prompt": "What is the capital of France?", "peer": "peer_A"},
        {"prompt": "What is the capital of France?", "peer": "peer_B"},  # same task, diff peer
        {"prompt": "Explain quantum entanglement.", "peer": "peer_A"},
        {"prompt": "Explain quantum entanglement.", "peer": "peer_C"},  # cache hit
        {"prompt": "Write a haiku about rain.", "peer": "peer_B"},
        {"prompt": "What is the capital of France?", "peer": "peer_D"},  # cache hit
    ]

    for i, task in enumerate(tasks, 1):
        t0 = time.time()
        result = caller.call(task)
        elapsed = time.time() - t0
        cached = elapsed < 0.1
        tag = "CACHED " if cached else "COMPUTED"
        print(f"  [{i}] {tag} ({elapsed:.3f}s) peer={task['peer']:8s} "
              f"prompt={task['prompt'][:40]:40s} → {result['response'][:40]}")

    print()
    print("Cache stats:")
    for k, v in cache.stats().items():
        print(f"  {k:20s}: {v}")

    # Test TTL expiry with short TTL
    print()
    print("--- TTL expiry test (TTL=1s) ---")
    short_cache = AgentResponseCache(max_size=8, ttl_seconds=1)
    short_caller = CachedAgentCaller(_demo_llm_handler, short_cache)
    task_t = {"prompt": "Quick test", "peer": "peer_X"}
    r1 = short_caller.call(task_t)
    print(f"  First call: computed, response={r1['response']}")
    r2 = short_caller.call(task_t)
    print(f"  Second call (immediate): cached, response={r2['response']}")
    print("  Sleeping 1.5s for TTL expiry...")
    time.sleep(1.5)
    r3 = short_caller.call(task_t)
    print(f"  Third call (after TTL): re-computed, response={r3['response']}")

    # Test LRU eviction
    print()
    print("--- LRU eviction test (max_size=2) ---")
    lru_cache = AgentResponseCache(max_size=2, ttl_seconds=300)
    lru_caller = CachedAgentCaller(_demo_llm_handler, lru_cache)
    lru_caller.call({"prompt": "task1", "peer": "p1"})
    lru_caller.call({"prompt": "task2", "peer": "p1"})
    lru_caller.call({"prompt": "task1", "peer": "p1"})  # touch task1 → task2 becomes LRU
    lru_caller.call({"prompt": "task3", "peer": "p1"})  # evict task2
    stats = lru_cache.stats()
    print(f"  Size after 4 ops: {stats['size']} (expected 2)")
    print(f"  LRU evictions: {stats['evictions_lru']} (expected 1)")
    print(f"  Hits: {stats['hits']}, Misses: {stats['misses']}")

    print()
    print("✓ All tests passed. Cache ready for A2A Mesh integration.")


if __name__ == "__main__":
    main()